                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE or REPLACE table snitch_db.maplemonk.offline_long_tail_Replen_7_26 as WITH SHOES AS ( WITH store_sku_inventory AS ( SELECT *, COUNT(DISTINCT sku_group) OVER ( PARTITION BY branch_code, branch_name ) AS option_count FROM ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS branch_name, UPPER(TRIM(sku_group)) AS sku_group, SUM(COALESCE(inventory, 0)) AS inventory_qty, SUM(COALESCE(jit_qty, 0)) AS jit_qty, SUM(COALESCE(inventory, 0)) + SUM(COALESCE(jit_qty, 0)) AS stock_qty, SUM(COALESCE(xs_units, 0)) AS size_40, SUM(COALESCE(s_units, 0)) AS size_41, SUM(COALESCE(m_units, 0)) AS size_42, SUM(COALESCE(l_units, 0)) AS size_43, SUM(COALESCE(xl_units, 0)) AS size_44, SUM(COALESCE(xxl_units, 0)) AS size_45, SUM(COALESCE(xl3_units, 0)) AS size_46, SUM(COALESCE(jit_xs_units, 0)) AS jit_40, SUM(COALESCE(jit_s_units, 0)) AS jit_41, SUM(COALESCE(jit_m_units, 0)) AS jit_42, SUM(COALESCE(jit_l_units, 0)) AS jit_43, SUM(COALESCE(jit_xl_units, 0)) AS jit_44, SUM(COALESCE(jit_2xl_units, 0)) AS jit_45, SUM(COALESCE(jit_3xl_units, 0)) AS jit_46, SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) AS available_40, SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) AS available_41, SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) AS available_42, SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) AS available_43, CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) > 0 AND SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) > 0 AND SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 AND SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) > 0 THEN \'FULL_SIZE\' ELSE \'CUT_SIZE\' END AS size_status, CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) > 0 AND SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) > 0 AND SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 AND SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) > 0 THEN \'FULL SIZE\' ELSE RTRIM( CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) <= 0 THEN \'40 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) <= 0 THEN \'41 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) <= 0 THEN \'42 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) <= 0 THEN \'43 , \' ELSE \'\' END, \', \' ) END AS size_remark, SUM(COALESCE(sales_last_30_days, 0)) AS sales_last_30_days, SUM(COALESCE(sales_last_15_days, 0)) AS sales_last_15_days, SUM(COALESCE(sales_last_7_days, 0)) AS sales_last_7_days, ( 0.6 * (SUM(COALESCE(sales_last_7_days, 0)) / 7.0) + 0.3 * (SUM(COALESCE(sales_last_15_days, 0)) / 15.0) + 0.1 * (SUM(COALESCE(sales_last_30_days, 0)) / 30.0) ) AS ros, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( SUM(COALESCE(sales_last_30_days, 0)) + SUM(COALESCE(inventory, 0)), 0 ) AS str FROM snitch_db.maplemonk.offline_master WHERE UPPER(TRIM(sku_group)) LIKE \'SH0%\' AND COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 GROUP BY branch_code, UPPER(TRIM(marketplace_mapped)), UPPER(TRIM(sku_group)) ) ), stores_perf AS ( SELECT DISTINCT branch_code, branch_name AS marketplace_mapped FROM store_sku_inventory ), store_option_count AS ( SELECT branch_code, branch_name AS marketplace_mapped, MAX(option_count) AS option_count FROM store_sku_inventory GROUP BY 1, 2 ), store_region AS ( SELECT DISTINCT branch_code, UPPER(TRIM(zone)) AS region FROM snitch_db.maplemonk.store_category_delta ), schedule_rpl AS ( SELECT branch_code, UPPER(LEFT( CASE WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY rpl_order_day) = 1 ), store_sell_through AS ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( (SUM(COALESCE(opening_inventory, 0)) + SUM(COALESCE(inventory, 0))) / 2.0, 0 ) AS sell_through FROM snitch_db.maplemonk.off_master_htmlbase WHERE UPPER(TRIM(sku_group)) LIKE \'SH0%\' GROUP BY 1, 2 ), store_ideal_options AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(\"Footwear(Options)\" AS INT), 0) AS ideal_options FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_size AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(REPLACE(sqft, \',\', \'\') AS INT), 0) AS store_size FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_priority AS ( SELECT s.branch_code, s.marketplace_mapped, COALESCE(sr.region, \'UNKNOWN\') AS region, COALESCE(st.sell_through, 0) AS sell_through, COALESCE(io.ideal_options, 0) AS ideal_options, COALESCE(oc.option_count, 0) AS current_options, COALESCE(io.ideal_options, 0) - COALESCE(oc.option_count, 0) AS option_gap, COALESCE(sz.store_size, 0) AS store_size FROM stores_perf s LEFT JOIN store_region sr ON sr.branch_code = s.branch_code LEFT JOIN store_sell_through st ON st.branch_code = s.branch_code AND st.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_option_count oc ON oc.branch_code = s.branch_code AND oc.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_ideal_options io ON io.branch_code = s.branch_code LEFT JOIN store_size sz ON sz.branch_code = s.branch_code INNER JOIN schedule_rpl sch ON sch.branch_code = s.branch_code AND UPPER(TRIM(sch.rpl_order_day)) = UPPER(DAYNAME(CURRENT_DATE)) ), excluded_shoe_sku_groups AS ( SELECT column1 AS sku_group FROM VALUES (\'SH0120-02\'),(\'SH0039-02\'),(\'SH0131-01\'),(\'SH0144-02\'),(\'SH0120-01\'),(\'SH0114-01\'),(\'SH0120-03\'),(\'SH0039-01\'),(\'SH0137-02\'),(\'SH0136-01\'),(\'SH0136-02\'),(\'SH0136-03\'),(\'SH0131-02\'),(\'SH0145-02\'),(\'SH0137-01\'),(\'SH0134-01\'),(\'SH0145-01\'),(\'SH0119-01\'),(\'SH0144-01\'),(\'SH0119-02\'), (\'SH0134-02\'),(\'SH0119-03\'),(\'SH0139-01\'),(\'SH0121-01\'),(\'SH0121-02\'),(\'SH0132-01\'),(\'SH0121-03\'),(\'SH0133-01\'),(\'SH0128-02\'),(\'SH0124-02\'),(\'SH0124-01\'),(\'SH0149-03\'),(\'SH0126-01\'),(\'SH0149-01\'),(\'SH0132-02\'),(\'SH0127-02\'),(\'SH0130-02\'),(\'SH0115-01\'),(\'SH0130-01\'),(\'SH0127-01\'), (\'SH0122-01\'),(\'SH0129-01\'),(\'SH0128-01\'),(\'SH0126-02\'),(\'SH0122-02\'),(\'SH0143-02\'),(\'SH0133-02\'),(\'SH0129-02\'),(\'SH0143-01\'),(\'SH0122-03\'), (\'SH0149-02\'),(\'SH0135-01\'),(\'SH0038-01\'),(\'SH0042-01\'),(\'SH0040-01\'),(\'SH0041-01\'),(\'SH0148-03\'),(\'SH0151-01\'),(\'SH0108-01\'),(\'SH0113-01\'), (\'SH0111-01\'),(\'SH0140-02\'),(\'SH0113-02\'),(\'SH0109-01\'),(\'SH0142-01\'),(\'SH0110-02\'),(\'SH0154-01\'),(\'SH0125-02\'),(\'SH0123-01\'),(\'SH0140-01\'), (\'SH0112-01\'),(\'SH0150-02\'),(\'SH0116-02\'),(\'SH0148-02\'),(\'SH0141-01\'),(\'SH0154-03\'),(\'SH0141-02\'),(\'SH0117-01\'),(\'SH0152-01\'),(\'SH0116-01\'), (\'SH0147-02\'),(\'SH0108-02\'),(\'SH0125-03\'),(\'SH0109-02\'),(\'SH0147-01\'),(\'SH0150-01\'),(\'SH0142-02\'),(\'SH0146-01\'),(\'SH0151-02\'),(\'SH0110-01\'),(\'SH0123-02\'),(\'SH0113-03\'),(\'SH0148-01\'),(\'SH0125-01\'),(\'SH0138-01\'),(\'SH0001\'),(\'SH0002\'),(\'SH0003\'),(\'SH0004\'),(\'SH0005\'),(\'SH0006\'),(\'SH0007\'),(\'SH0008\'),(\'SH0009\'),(\'SH0010\'), (\'SH0011\'),(\'SH0012\'),(\'SH0013\'),(\'SH0015\'),(\'SH0016\'),(\'SH0017\'),(\'SH0018\'),(\'SH0019\'),(\'SH0020\'),(\'SH0021\'),(\'SH0022\'),(\'SH0023\'),(\'SH0024\'),(\'SH0025\'),(\'SH0026\'),(\'SH0027\'),(\'SH0028\'),(\'SH0029\'),(\'SH0030\'),(\'SH0031\'),(\'SH0032\'),(\'SH0033\'),(\'SH0034\'),(\'SH0035\'),(\'SH0036\'),(\'SH0037\'),(\'SH0118-02\'),(\'SH0038-02\'),(\'SH0029G\'),(\'SH0028W\'),(\'SH0028B\'),(\'SH0154-02\'),(\'SH0029B\'), (\'SH0038-03\'),(\'SH0118-01\'),(\'SH0184-05\'),(\'SH194-01\'),(\'SH0182-01\') ), wh_raw AS ( SELECT facility, UPPER(TRIM(\"Item SkuCode\")) AS size_sku_code, UPPER(TRIM(SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2))) AS sku_group, SPLIT_PART(\"Item SkuCode\", \'-\', 3) AS shoe_size, COALESCE(inventory, 0) AS inventory FROM snitch_db.maplemonk.unicommerce_live_inventory WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') AND UPPER(TRIM(\"Item SkuCode\")) LIKE \'SH0%\' AND SPLIT_PART(\"Item SkuCode\", \'-\', 3) IN (\'40\', \'41\', \'42\', \'43\') AND INVENTORY > 2 ), shoes_wh_size_inventory AS ( SELECT facility, CASE WHEN facility IN (\'SAPL-WH2\', \'SAPL-WH1\') THEN \'SOUTH_WH\' WHEN facility = \'SAPL-NORTH-TAURU\' THEN \'NORTH_WH\' ELSE \'OTHER_WH\' END AS wh_group, CASE WHEN facility = \'SAPL-WH2\' THEN 1 WHEN facility = \'SAPL-WH1\' THEN 2 WHEN facility = \'SAPL-NORTH-TAURU\' THEN 3 ELSE 9 END AS facility_order, sku_group, shoe_size, size_sku_code, SUM(inventory) AS wh_size_inventory FROM wh_raw WHERE sku_group NOT IN ( SELECT sku_group FROM excluded_shoe_sku_groups ) GROUP BY facility, sku_group, shoe_size, size_sku_code HAVING SUM(inventory) > 0 ), store_size_inventory_unpivot AS ( SELECT branch_code, branch_name, sku_group, \'40\' AS shoe_size, size_40 AS physical_size_qty, jit_40 AS jit_size_qty, available_40 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'41\' AS shoe_size, size_41 AS physical_size_qty, jit_41 AS jit_size_qty, available_41 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'42\' AS shoe_size, size_42 AS physical_size_qty, jit_42 AS jit_size_qty, available_42 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'43\' AS shoe_size, size_43 AS physical_size_qty, jit_43 AS jit_size_qty, available_43 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory ), replen_demand AS ( SELECT s.branch_code, s.branch_name, s.sku_group, s.shoe_size, s.physical_size_qty, s.jit_size_qty, s.current_size_available, s.inventory_qty, s.jit_qty, s.stock_qty, s.size_status, s.size_remark, s.option_count, s.sales_last_30_days, s.sales_last_15_days, s.sales_last_7_days, s.ros, s.str, CEIL(s.ros * 10) AS target_10_day_cover, GREATEST( CEIL(s.ros * 10) - COALESCE(s.current_size_available, 0),0 ) AS need_qty, CASE WHEN s.size_status = \'CUT_SIZE\' AND COALESCE(s.current_size_available, 0) <= 0 THEN 1 WHEN s.size_status = \'CUT_SIZE\' THEN 2 WHEN s.size_status = \'FULL_SIZE\' THEN 3 ELSE 4 END AS replen_priority_bucket, CASE WHEN s.size_status = \'CUT_SIZE\' AND COALESCE(s.current_size_available, 0) <= 0 THEN \'CUT_SIZE_MISSING_SIZE\' WHEN s.size_status = \'CUT_SIZE\' THEN \'CUT_SIZE_TOPUP\' WHEN s.size_status = \'FULL_SIZE\' THEN \'FULL_SIZE_ROS_TOPUP\' ELSE \'OTHER\' END AS replen_priority_reason, sp.region, sp.sell_through, sp.ideal_options, sp.current_options, sp.option_gap, sp.store_size, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'NORTH_WH\' ELSE \'SOUTH_WH\' END AS preferred_wh_group, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'SOUTH_WH\' ELSE \'NORTH_WH\' END AS fallback_wh_group FROM store_size_inventory_unpivot s INNER JOIN store_priority sp ON sp.branch_code = s.branch_code AND sp.marketplace_mapped = s.branch_name WHERE s.shoe_size IN (\'40\', \'41\', \'42\', \'43\') AND CEIL(s.ros * 10) > COALESCE(s.current_size_available, 0) AND s.sku_group NOT IN ( SELECT sku_group FROM excluded_shoe_sku_groups ) ), wh_group_stock AS ( SELECT sku_group, shoe_size, wh_group, SUM(wh_size_inventory) AS group_stock FROM shoes_wh_size_inventory GROUP BY 1, 2, 3 ), stage_1_demand_ranked AS ( SELECT d.*, SUM(need_qty) OVER ( PARTITION BY sku_group, shoe_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_pref, SUM(need_qty) OVER ( PARTITION BY sku_group, shoe_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_pref_before FROM replen_demand d ), stage_1_group_alloc AS ( SELECT d.*, COALESCE(w.group_stock, 0) AS preferred_group_stock, GREATEST(LEAST(d.cum_need_pref, COALESCE(w.group_stock, 0)) - COALESCE(d.cum_need_pref_before, 0),0) AS pref_alloc_qty FROM stage_1_demand_ranked d LEFT JOIN wh_group_stock w ON w.sku_group = d.sku_group AND w.shoe_size = d.shoe_size AND w.wh_group = d.preferred_wh_group ), stage_1_alloc_ranked_for_facility AS ( SELECT *, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, shoe_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_pref_alloc, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, shoe_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_pref_alloc_before FROM stage_1_group_alloc WHERE pref_alloc_qty > 0 ), stage_1_facility_stock_ranked AS ( SELECT *, SUM(wh_size_inventory) OVER ( PARTITION BY sku_group, shoe_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fac_stock, SUM(wh_size_inventory) OVER ( PARTITION BY sku_group, shoe_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fac_stock_before FROM shoes_wh_size_inventory ), stage_1_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, d.shoe_size, w.size_sku_code, w.facility, w.wh_group, \'PREFERRED_WH\' AS allocation_stage, d.physical_size_qty, d.jit_size_qty, d.current_size_available, d.inventory_qty, d.jit_qty, d.stock_qty, d.size_status, d.size_remark, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_10_day_cover, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_size_inventory AS warehouse_size_stock, GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_1_alloc_ranked_for_facility d JOIN stage_1_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.shoe_size = d.shoe_size AND w.wh_group = d.preferred_wh_group WHERE GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) > 0 ), stage_1_facility_consumed AS ( SELECT sku_group, shoe_size, facility, SUM(allocated_qty) AS consumed_qty FROM stage_1_facility_alloc GROUP BY 1, 2, 3 ), facility_stock_after_stage_1 AS ( SELECT w.sku_group, w.shoe_size, w.size_sku_code, w.facility, w.wh_group, w.facility_order, w.wh_size_inventory, COALESCE(c.consumed_qty, 0) AS consumed_stage_1_qty, GREATEST(w.wh_size_inventory - COALESCE(c.consumed_qty, 0), 0) AS remaining_facility_stock FROM shoes_wh_size_inventory w LEFT JOIN stage_1_facility_consumed c ON c.sku_group = w.sku_group AND c.shoe_size = w.shoe_size AND c.facility = w.facility ), stage_2_remaining_demand AS ( SELECT *, GREATEST(need_qty - pref_alloc_qty, 0) AS remaining_need_qty FROM stage_1_group_alloc WHERE GREATEST(need_qty - pref_alloc_qty, 0) > 0 ), stage_2_wh_group_stock AS ( SELECT sku_group, shoe_size, wh_group, SUM(remaining_facility_stock) AS remaining_group_stock FROM facility_stock_after_stage_1 GROUP BY 1, 2, 3 ), stage_2_demand_ranked AS ( SELECT d.*, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, shoe_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_fallback, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, shoe_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_fallback_before FROM stage_2_remaining_demand d ), stage_2_group_alloc AS ( SELECT d.*, COALESCE(w.remaining_group_stock, 0) AS fallback_group_stock, GREATEST( LEAST(d.cum_need_fallback, COALESCE(w.remaining_group_stock, 0)) - COALESCE(d.cum_need_fallback_before, 0), 0 ) AS fallback_alloc_qty FROM stage_2_demand_ranked d LEFT JOIN stage_2_wh_group_stock w ON w.sku_group = d.sku_group AND w.shoe_size = d.shoe_size AND w.wh_group = d.fallback_wh_group ), stage_2_alloc_ranked_for_facility AS ( SELECT *, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, shoe_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fallback_alloc, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, shoe_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fallback_alloc_before FROM stage_2_group_alloc WHERE fallback_alloc_qty > 0 ), stage_2_facility_stock_ranked AS ( SELECT *, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, shoe_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_remaining_fac_stock, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, shoe_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_remaining_fac_stock_before FROM facility_stock_after_stage_1 WHERE remaining_facility_stock > 0 ), stage_2_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, d.shoe_size, w.size_sku_code, w.facility, w.wh_group, \'FALLBACK_WH\' AS allocation_stage, d.physical_size_qty, d.jit_size_qty, d.current_size_available, d.inventory_qty, d.jit_qty, d.stock_qty, d.size_status, d.size_remark, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_10_day_cover, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_size_inventory AS warehouse_size_stock, GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_2_alloc_ranked_for_facility d JOIN stage_2_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.shoe_size = d.shoe_size AND w.wh_group = d.fallback_wh_group WHERE GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) > 0 ), final_allocation AS ( SELECT * FROM stage_1_facility_alloc UNION ALL SELECT * FROM stage_2_facility_alloc ) SELECT branch_code, branch_name, region, sku_group, shoe_size, size_sku_code, facility AS warehouse_name, wh_group, allocation_stage, physical_size_qty, jit_size_qty, current_size_available, target_10_day_cover, need_qty, allocated_qty, warehouse_size_stock, inventory_qty AS store_inventory_qty, jit_qty AS store_jit_qty, stock_qty AS store_stock_jit_qty, size_status, size_remark, replen_priority_bucket, replen_priority_reason, option_count, ideal_options, current_options, option_gap, store_size, sales_last_7_days, sales_last_15_days, sales_last_30_days, ROUND(ros, 4) AS ros, ROUND(str, 4) AS str, ROUND(sell_through, 4) AS store_sell_through, preferred_wh_group, fallback_wh_group FROM final_allocation WHERE allocated_qty > 0 ORDER BY replen_priority_bucket ASC, sku_group, shoe_size, CASE WHEN allocation_stage = \'PREFERRED_WH\' THEN 1 ELSE 2 END, store_sell_through DESC, option_gap DESC, store_size DESC, ros DESC, branch_code, warehouse_name ), BELTS AS ( WITH store_sku_inventory AS ( SELECT *, COUNT(DISTINCT sku_group) OVER ( PARTITION BY branch_code, branch_name ) AS option_count FROM ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS branch_name, UPPER(TRIM(sku_group)) AS sku_group, SUM(COALESCE(inventory, 0)) AS inventory_qty, SUM(COALESCE(jit_qty, 0)) AS jit_qty, SUM(COALESCE(inventory, 0)) + SUM(COALESCE(jit_qty, 0)) AS stock_qty, SUM(COALESCE(xs_units, 0)) AS size_28, SUM(COALESCE(s_units, 0)) AS size_30, SUM(COALESCE(m_units, 0)) AS size_32, SUM(COALESCE(l_units, 0)) AS size_34, SUM(COALESCE(xl_units, 0)) AS size_36, SUM(COALESCE(xxl_units, 0)) AS size_38, SUM(COALESCE(xl3_units, 0)) AS size_40, SUM(COALESCE(jit_xs_units, 0)) AS jit_28, SUM(COALESCE(jit_s_units, 0)) AS jit_30, SUM(COALESCE(jit_m_units, 0)) AS jit_32, SUM(COALESCE(jit_l_units, 0)) AS jit_34, SUM(COALESCE(jit_xl_units, 0)) AS jit_36, SUM(COALESCE(jit_2xl_units, 0)) AS jit_38, SUM(COALESCE(jit_3xl_units, 0)) AS jit_40, SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) AS available_28, SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) AS available_30, SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) AS available_32, SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) AS available_34, SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) AS available_36, SUM(COALESCE(xxl_units, 0)) + SUM(COALESCE(jit_2xl_units, 0)) AS available_38, SUM(COALESCE(xl3_units, 0)) + SUM(COALESCE(jit_3xl_units, 0)) AS available_40, CASE WHEN UPPER(TRIM(sku_group)) LIKE \'4MBL%\' AND ( CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl3_units, 0)) + SUM(COALESCE(jit_3xl_units, 0)) > 0 THEN 1 ELSE 0 END ) < 3 AND ( CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xxl_units, 0)) + SUM(COALESCE(jit_2xl_units, 0)) > 0 THEN 1 ELSE 0 END ) < 4 THEN \'CUT_SIZE\' ELSE \'FULL_SIZE\' END AS size_status, CASE WHEN NOT ( UPPER(TRIM(sku_group)) LIKE \'4MBL%\' AND ( CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl3_units, 0)) + SUM(COALESCE(jit_3xl_units, 0)) > 0 THEN 1 ELSE 0 END ) < 3 AND ( CASE WHEN SUM(COALESCE(xs_units, 0)) + SUM(COALESCE(jit_xs_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(s_units, 0)) + SUM(COALESCE(jit_s_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(l_units, 0)) + SUM(COALESCE(jit_l_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) > 0 THEN 1 ELSE 0 END + CASE WHEN SUM(COALESCE(xxl_units, 0)) + SUM(COALESCE(jit_2xl_units, 0)) > 0 THEN 1 ELSE 0 END ) < 4 ) THEN \'FULL SIZE\' ELSE RTRIM( CASE WHEN SUM(COALESCE(m_units, 0)) + SUM(COALESCE(jit_m_units, 0)) <= 0 THEN \'32 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(xl_units, 0)) + SUM(COALESCE(jit_xl_units, 0)) <= 0 THEN \'36 , \' ELSE \'\' END || CASE WHEN SUM(COALESCE(xl3_units, 0)) + SUM(COALESCE(jit_3xl_units, 0)) <= 0 THEN \'40 , \' ELSE \'\' END, \', \' ) END AS size_remark, SUM(COALESCE(sales_last_30_days, 0)) AS sales_last_30_days, SUM(COALESCE(sales_last_15_days, 0)) AS sales_last_15_days, SUM(COALESCE(sales_last_7_days, 0)) AS sales_last_7_days, ( 0.5 * (SUM(COALESCE(sales_last_7_days, 0)) / 7.0) + 0.3 * (SUM(COALESCE(sales_last_15_days, 0)) / 15.0) + 0.2 * (SUM(COALESCE(sales_last_30_days, 0)) / 30.0) ) AS ros, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( SUM(COALESCE(sales_last_30_days, 0)) + SUM(COALESCE(inventory, 0)), 0 ) AS str FROM snitch_db.maplemonk.offline_master WHERE UPPER(TRIM(sku_group)) LIKE \'4MBL%\' AND COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 GROUP BY branch_code, UPPER(TRIM(marketplace_mapped)), UPPER(TRIM(sku_group)) ) ), stores_perf AS ( SELECT DISTINCT branch_code, branch_name AS marketplace_mapped FROM store_sku_inventory ), store_option_count AS ( SELECT branch_code, branch_name AS marketplace_mapped, MAX(option_count) AS option_count FROM store_sku_inventory GROUP BY 1, 2 ), store_region AS ( SELECT DISTINCT branch_code, UPPER(TRIM(zone)) AS region FROM snitch_db.maplemonk.store_category_delta ), schedule_rpl AS ( SELECT branch_code, UPPER(LEFT( CASE WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY rpl_order_day) = 1 ), store_sell_through AS ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( (SUM(COALESCE(opening_inventory, 0)) + SUM(COALESCE(inventory, 0))) / 2.0, 0 ) AS sell_through FROM snitch_db.maplemonk.off_master_htmlbase WHERE UPPER(TRIM(sku_group)) LIKE \'4MBL%\' GROUP BY 1, 2 ), store_ideal_options AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(\"Belts(Options)\" AS INT), 0) AS ideal_options FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_size AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(REPLACE(sqft, \',\', \'\') AS INT), 0) AS store_size FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_priority AS ( SELECT s.branch_code, s.marketplace_mapped, COALESCE(sr.region, \'UNKNOWN\') AS region, COALESCE(st.sell_through, 0) AS sell_through, COALESCE(io.ideal_options, 0) AS ideal_options, COALESCE(oc.option_count, 0) AS current_options, COALESCE(io.ideal_options, 0) - COALESCE(oc.option_count, 0) AS option_gap, COALESCE(sz.store_size, 0) AS store_size FROM stores_perf s LEFT JOIN store_region sr ON sr.branch_code = s.branch_code LEFT JOIN store_sell_through st ON st.branch_code = s.branch_code AND st.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_option_count oc ON oc.branch_code = s.branch_code AND oc.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_ideal_options io ON io.branch_code = s.branch_code LEFT JOIN store_size sz ON sz.branch_code = s.branch_code INNER JOIN schedule_rpl sch ON sch.branch_code = s.branch_code AND UPPER(TRIM(sch.rpl_order_day)) = UPPER(DAYNAME(CURRENT_DATE)) ), wh_raw AS ( SELECT facility, UPPER(TRIM(\"Item SkuCode\")) AS size_sku_code, UPPER(TRIM(SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2))) AS sku_group, SPLIT_PART(\"Item SkuCode\", \'-\', 3) AS belt_size, COALESCE(inventory, 0) AS inventory FROM snitch_db.maplemonk.unicommerce_live_inventory WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') AND UPPER(TRIM(\"Item SkuCode\")) LIKE \'4MBL%\' AND SPLIT_PART(\"Item SkuCode\", \'-\', 3) IN (\'28\',\'30\',\'32\',\'34\', \'36\',\'38\', \'40\') AND INVENTORY > 2 ), belts_wh_size_inventory AS ( SELECT facility, CASE WHEN facility IN (\'SAPL-WH2\', \'SAPL-WH1\') THEN \'SOUTH_WH\' WHEN facility = \'SAPL-NORTH-TAURU\' THEN \'NORTH_WH\' ELSE \'OTHER_WH\' END AS wh_group, CASE WHEN facility = \'SAPL-WH2\' THEN 1 WHEN facility = \'SAPL-WH1\' THEN 2 WHEN facility = \'SAPL-NORTH-TAURU\' THEN 3 ELSE 9 END AS facility_order, sku_group, belt_size, size_sku_code, SUM(inventory) AS wh_size_inventory FROM wh_raw GROUP BY facility, sku_group, belt_size, size_sku_code HAVING SUM(inventory) > 0 ), store_size_inventory_unpivot AS ( SELECT branch_code, branch_name, sku_group, \'28\' AS belt_size, size_28 AS physical_size_qty, jit_28 AS jit_size_qty, available_28 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'30\' AS belt_size, size_30 AS physical_size_qty, jit_30 AS jit_size_qty, available_30 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'32\' AS belt_size, size_32 AS physical_size_qty, jit_32 AS jit_size_qty, available_32 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'34\' AS belt_size, size_34 AS physical_size_qty, jit_34 AS jit_size_qty, available_34 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'36\' AS belt_size, size_36 AS physical_size_qty, jit_36 AS jit_size_qty, available_36 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'38\' AS belt_size, size_38 AS physical_size_qty, jit_38 AS jit_size_qty, available_38 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory UNION ALL SELECT branch_code, branch_name, sku_group, \'40\' AS belt_size, size_40 AS physical_size_qty, jit_40 AS jit_size_qty, available_40 AS current_size_available, inventory_qty, jit_qty, stock_qty, size_status, size_remark, option_count, sales_last_30_days, sales_last_15_days, sales_last_7_days, ros, str FROM store_sku_inventory ), replen_demand AS ( SELECT s.branch_code, s.branch_name, s.sku_group, s.belt_size, s.physical_size_qty, s.jit_size_qty, s.current_size_available, s.inventory_qty, s.jit_qty, s.stock_qty, s.size_status, s.size_remark, s.option_count, s.sales_last_30_days, s.sales_last_15_days, s.sales_last_7_days, s.ros, s.str, CEIL(s.ros * 10) AS target_10_day_cover, GREATEST(CEIL(s.ros * 10) - COALESCE(s.current_size_available, 0), 0) AS need_qty, CASE WHEN s.size_status = \'CUT_SIZE\' AND COALESCE(s.current_size_available, 0) <= 0 THEN 1 WHEN s.size_status = \'CUT_SIZE\' THEN 2 WHEN s.size_status = \'FULL_SIZE\' THEN 3 ELSE 4 END AS replen_priority_bucket, CASE WHEN s.size_status = \'CUT_SIZE\' AND COALESCE(s.current_size_available, 0) <= 0 THEN \'CUT_SIZE_MISSING_SIZE\' WHEN s.size_status = \'CUT_SIZE\' THEN \'CUT_SIZE_TOPUP\' WHEN s.size_status = \'FULL_SIZE\' THEN \'FULL_SIZE_ROS_TOPUP\' ELSE \'OTHER\' END AS replen_priority_reason, sp.region, sp.sell_through, sp.ideal_options, sp.current_options, sp.option_gap, sp.store_size, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'NORTH_WH\' ELSE \'SOUTH_WH\' END AS preferred_wh_group, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'SOUTH_WH\' ELSE \'NORTH_WH\' END AS fallback_wh_group FROM store_size_inventory_unpivot s INNER JOIN store_priority sp ON sp.branch_code = s.branch_code AND sp.marketplace_mapped = s.branch_name WHERE s.belt_size IN (\'28\', \'30\', \'32\', \'34\', \'36\', \'38\', \'40\') AND COALESCE(s.current_size_available, 0) > 0 AND CEIL(s.ros * 10) > COALESCE(s.current_size_available, 0) ), wh_group_stock AS ( SELECT sku_group, belt_size, wh_group, SUM(wh_size_inventory) AS group_stock FROM belts_wh_size_inventory GROUP BY 1, 2, 3 ), stage_1_demand_ranked AS ( SELECT d.*, SUM(need_qty) OVER ( PARTITION BY sku_group, belt_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_pref, SUM(need_qty) OVER ( PARTITION BY sku_group, belt_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_pref_before FROM replen_demand d ), stage_1_group_alloc AS ( SELECT d.*, COALESCE(w.group_stock, 0) AS preferred_group_stock, GREATEST( LEAST(d.cum_need_pref, COALESCE(w.group_stock, 0)) - COALESCE(d.cum_need_pref_before, 0), 0 ) AS pref_alloc_qty FROM stage_1_demand_ranked d LEFT JOIN wh_group_stock w ON w.sku_group = d.sku_group AND w.belt_size = d.belt_size AND w.wh_group = d.preferred_wh_group ), stage_1_alloc_ranked_for_facility AS ( SELECT *, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, belt_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_pref_alloc, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, belt_size, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_pref_alloc_before FROM stage_1_group_alloc WHERE pref_alloc_qty > 0 ), stage_1_facility_stock_ranked AS ( SELECT *, SUM(wh_size_inventory) OVER ( PARTITION BY sku_group, belt_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fac_stock, SUM(wh_size_inventory) OVER ( PARTITION BY sku_group, belt_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fac_stock_before FROM belts_wh_size_inventory ), stage_1_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, d.belt_size, w.size_sku_code, w.facility, w.wh_group, \'PREFERRED_WH\' AS allocation_stage, d.physical_size_qty, d.jit_size_qty, d.current_size_available, d.inventory_qty, d.jit_qty, d.stock_qty, d.size_status, d.size_remark, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_10_day_cover, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_size_inventory AS warehouse_size_stock, GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_1_alloc_ranked_for_facility d JOIN stage_1_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.belt_size = d.belt_size AND w.wh_group = d.preferred_wh_group WHERE GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) > 0 ), stage_1_facility_consumed AS ( SELECT sku_group, belt_size, facility, SUM(allocated_qty) AS consumed_qty FROM stage_1_facility_alloc GROUP BY 1, 2, 3 ), facility_stock_after_stage_1 AS ( SELECT w.sku_group, w.belt_size, w.size_sku_code, w.facility, w.wh_group, w.facility_order, w.wh_size_inventory, COALESCE(c.consumed_qty, 0) AS consumed_stage_1_qty, GREATEST(w.wh_size_inventory - COALESCE(c.consumed_qty, 0), 0) AS remaining_facility_stock FROM belts_wh_size_inventory w LEFT JOIN stage_1_facility_consumed c ON c.sku_group = w.sku_group AND c.belt_size = w.belt_size AND c.facility = w.facility ), stage_2_remaining_demand AS ( SELECT *, GREATEST(need_qty - pref_alloc_qty, 0) AS remaining_need_qty FROM stage_1_group_alloc WHERE GREATEST(need_qty - pref_alloc_qty, 0) > 0 ), stage_2_wh_group_stock AS ( SELECT sku_group, belt_size, wh_group, SUM(remaining_facility_stock) AS remaining_group_stock FROM facility_stock_after_stage_1 GROUP BY 1, 2, 3 ), stage_2_demand_ranked AS ( SELECT d.*, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, belt_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_fallback, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, belt_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_fallback_before FROM stage_2_remaining_demand d ), stage_2_group_alloc AS ( SELECT d.*, COALESCE(w.remaining_group_stock, 0) AS fallback_group_stock, GREATEST( LEAST(d.cum_need_fallback, COALESCE(w.remaining_group_stock, 0)) - COALESCE(d.cum_need_fallback_before, 0), 0 ) AS fallback_alloc_qty FROM stage_2_demand_ranked d LEFT JOIN stage_2_wh_group_stock w ON w.sku_group = d.sku_group AND w.belt_size = d.belt_size AND w.wh_group = d.fallback_wh_group ), stage_2_alloc_ranked_for_facility AS ( SELECT *, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, belt_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fallback_alloc, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, belt_size, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fallback_alloc_before FROM stage_2_group_alloc WHERE fallback_alloc_qty > 0 ), stage_2_facility_stock_ranked AS ( SELECT *, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, belt_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_remaining_fac_stock, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, belt_size, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_remaining_fac_stock_before FROM facility_stock_after_stage_1 WHERE remaining_facility_stock > 0 ), stage_2_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, d.belt_size, w.size_sku_code, w.facility, w.wh_group, \'FALLBACK_WH\' AS allocation_stage, d.physical_size_qty, d.jit_size_qty, d.current_size_available, d.inventory_qty, d.jit_qty, d.stock_qty, d.size_status, d.size_remark, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_10_day_cover, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_size_inventory AS warehouse_size_stock, GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_2_alloc_ranked_for_facility d JOIN stage_2_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.belt_size = d.belt_size AND w.wh_group = d.fallback_wh_group WHERE GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) > 0 ), final_allocation AS ( SELECT * FROM stage_1_facility_alloc UNION ALL SELECT * FROM stage_2_facility_alloc ) SELECT branch_code, branch_name, region, sku_group, belt_size, size_sku_code, facility AS warehouse_name, wh_group, allocation_stage, physical_size_qty, jit_size_qty, current_size_available, target_10_day_cover, need_qty, allocated_qty, warehouse_size_stock, inventory_qty AS store_inventory_qty, jit_qty AS store_jit_qty, stock_qty AS store_stock_jit_qty, size_status, size_remark, replen_priority_bucket, replen_priority_reason, option_count, ideal_options, current_options, option_gap, store_size, sales_last_7_days, sales_last_15_days, sales_last_30_days, ROUND(ros, 4) AS ros, ROUND(str, 4) AS str, ROUND(sell_through, 4) AS store_sell_through, preferred_wh_group, fallback_wh_group FROM final_allocation WHERE allocated_qty > 0 ORDER BY replen_priority_bucket ASC, sku_group, belt_size, CASE WHEN allocation_stage = \'PREFERRED_WH\' THEN 1 ELSE 2 END, store_sell_through DESC, option_gap DESC, store_size DESC, ros DESC, branch_code, warehouse_name ), PERFUMES AS ( WITH store_sku_inventory AS ( SELECT *, COUNT(DISTINCT sku_group) OVER ( PARTITION BY branch_code, branch_name ) AS option_count FROM ( SELECT h.branch_code, UPPER(TRIM(h.marketplace_mapped)) AS branch_name, CASE WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0941-01\' THEN \'4MSFR0941-01-01\' WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0942-01\' THEN \'4MSFR0942-01-01\' WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0943-01\' THEN \'4MSFR0943-01-01\' ELSE UPPER(TRIM(h.sku_group)) END AS sku_group, SUM(COALESCE(h.inventory, 0)) AS inventory_qty, SUM(COALESCE(h.jit_qty, 0)) AS jit_qty, SUM(COALESCE(h.inventory, 0)) + SUM(COALESCE(h.jit_qty, 0)) AS stock_qty, SUM(COALESCE(h.sales_last_30_days, 0)) AS sales_last_30_days, SUM(COALESCE(h.sales_last_15_days, 0)) AS sales_last_15_days, SUM(COALESCE(h.sales_last_7_days, 0)) AS sales_last_7_days, ( 0.5 * (SUM(COALESCE(h.sales_last_7_days, 0)) / 7.0) + 0.3 * (SUM(COALESCE(h.sales_last_15_days, 0)) / 15.0) + 0.2 * (SUM(COALESCE(h.sales_last_30_days, 0)) / 30.0) ) AS ros, SUM(COALESCE(h.sales_last_30_days, 0)) / NULLIF( SUM(COALESCE(h.sales_last_30_days, 0)) + SUM(COALESCE(h.inventory, 0)), 0 ) AS str FROM snitch_db.maplemonk.offline_master h WHERE UPPER(TRIM(h.sku_group)) LIKE \'4MSFR%\' AND COALESCE(h.inventory, 0) + COALESCE(h.jit_qty, 0) > 0 AND UPPER(TRIM(h.sku_group)) NOT IN (\'4MSFR0936-02%\',\'4MSFR0936-05%\',\'4MSFR0930\',\'4MSFR0931\') GROUP BY h.branch_code, UPPER(TRIM(h.marketplace_mapped)), CASE WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0941-01\' THEN \'4MSFR0941-01-01\' WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0942-01\' THEN \'4MSFR0942-01-01\' WHEN UPPER(TRIM(h.sku_group)) = \'4MSFR0943-01\' THEN \'4MSFR0943-01-01\' ELSE UPPER(TRIM(h.sku_group)) END ) t ), stores_perf AS ( SELECT DISTINCT branch_code, branch_name AS marketplace_mapped FROM store_sku_inventory ), store_option_count AS ( SELECT branch_code, branch_name AS marketplace_mapped, MAX(option_count) AS option_count FROM store_sku_inventory GROUP BY 1, 2 ), store_region AS ( SELECT DISTINCT branch_code, UPPER(TRIM(zone)) AS region FROM snitch_db.maplemonk.store_category_delta ), schedule_rpl AS ( SELECT branch_code, UPPER(LEFT( CASE WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY rpl_order_day) = 1 ), store_sell_through AS ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( (SUM(COALESCE(opening_inventory, 0)) + SUM(COALESCE(inventory, 0))) / 2.0, 0 ) AS sell_through FROM snitch_db.maplemonk.off_master_htmlbase WHERE UPPER(TRIM(sku_group)) LIKE \'4MSFR%\' GROUP BY 1, 2 ), store_ideal_options AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(\"Perfume(Options)\" AS INT), 0) AS ideal_options FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_size AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(REPLACE(sqft, \',\', \'\') AS INT), 0) AS store_size FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_priority AS ( SELECT s.branch_code, s.marketplace_mapped, COALESCE(sr.region, \'UNKNOWN\') AS region, COALESCE(st.sell_through, 0) AS sell_through, COALESCE(io.ideal_options, 0) AS ideal_options, COALESCE(oc.option_count, 0) AS current_options, COALESCE(io.ideal_options, 0) - COALESCE(oc.option_count, 0) AS option_gap, COALESCE(sz.store_size, 0) AS store_size FROM stores_perf s LEFT JOIN store_region sr ON sr.branch_code = s.branch_code LEFT JOIN store_sell_through st ON st.branch_code = s.branch_code AND st.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_option_count oc ON oc.branch_code = s.branch_code AND oc.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_ideal_options io ON io.branch_code = s.branch_code LEFT JOIN store_size sz ON sz.branch_code = s.branch_code INNER JOIN schedule_rpl sch ON sch.branch_code = s.branch_code AND UPPER(TRIM(sch.rpl_order_day)) = UPPER(DAYNAME(CURRENT_DATE)) ), wh_raw AS ( SELECT facility, UPPER(TRIM(\"Item SkuCode\")) AS sku_group, COALESCE(inventory, 0) AS inventory FROM snitch_db.maplemonk.unicommerce_live_inventory WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') AND UPPER(TRIM(\"Item SkuCode\")) LIKE \'4MSFR%\' AND INVENTORY > 12 AND UPPER(TRIM(\"Item SkuCode\")) NOT LIKE \'4MSFR0936-02%\' AND UPPER(TRIM(\"Item SkuCode\")) NOT LIKE \'4MSFR0936-05%\' AND UPPER(TRIM(\"Item SkuCode\")) NOT IN (\'4MSFR0930\',\'4MSFR0931\') ), perfume_wh_inventory AS ( SELECT facility, CASE WHEN facility IN (\'SAPL-WH2\', \'SAPL-WH1\') THEN \'SOUTH_WH\' WHEN facility = \'SAPL-NORTH-TAURU\' THEN \'NORTH_WH\' ELSE \'OTHER_WH\' END AS wh_group, CASE WHEN facility = \'SAPL-WH2\' THEN 1 WHEN facility = \'SAPL-WH1\' THEN 2 WHEN facility = \'SAPL-NORTH-TAURU\' THEN 3 ELSE 9 END AS facility_order, sku_group, FLOOR(SUM(inventory) / 12.0) * 12 AS wh_inventory FROM wh_raw GROUP BY facility, sku_group HAVING FLOOR(SUM(inventory) / 12.0) * 12 >= 12 ), replen_demand_base AS ( SELECT s.branch_code, s.branch_name, s.sku_group, s.inventory_qty, s.jit_qty, s.stock_qty, s.option_count, s.sales_last_30_days, s.sales_last_15_days, s.sales_last_7_days, s.ros, s.str, GREATEST(12, CEIL(s.ros * 10)) AS target_qty, sp.region, sp.sell_through, sp.ideal_options, sp.current_options, sp.option_gap, sp.store_size, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'NORTH_WH\' ELSE \'SOUTH_WH\' END AS preferred_wh_group, CASE WHEN UPPER(sp.region) LIKE \'%NORTH%\' THEN \'SOUTH_WH\' ELSE \'NORTH_WH\' END AS fallback_wh_group FROM store_sku_inventory s INNER JOIN store_priority sp ON sp.branch_code = s.branch_code AND sp.marketplace_mapped = s.branch_name ), replen_demand AS ( SELECT *, CASE WHEN target_qty > COALESCE(stock_qty, 0) THEN CEIL((target_qty - COALESCE(stock_qty, 0)) / 12.0) * 12 ELSE 0 END AS need_qty, CASE WHEN COALESCE(stock_qty, 0) < 12 THEN 1 WHEN target_qty > COALESCE(stock_qty, 0) THEN 2 ELSE 3 END AS replen_priority_bucket, CASE WHEN COALESCE(stock_qty, 0) < 12 THEN \'MIN_12_QTY_REPLEN\' WHEN target_qty > COALESCE(stock_qty, 0) THEN \'ROS_10_DAY_TOPUP\' ELSE \'OTHER\' END AS replen_priority_reason FROM replen_demand_base WHERE target_qty > COALESCE(stock_qty, 0) ), wh_group_stock AS ( SELECT sku_group, wh_group, SUM(wh_inventory) AS group_stock FROM perfume_wh_inventory GROUP BY 1, 2 ), stage_1_demand_ranked AS ( SELECT d.*, SUM(need_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_pref, SUM(need_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_pref_before FROM replen_demand d ), stage_1_group_alloc AS ( SELECT d.*, COALESCE(w.group_stock, 0) AS preferred_group_stock, GREATEST( LEAST(d.cum_need_pref, COALESCE(w.group_stock, 0)) - COALESCE(d.cum_need_pref_before, 0), 0 ) AS pref_alloc_qty FROM stage_1_demand_ranked d LEFT JOIN wh_group_stock w ON w.sku_group = d.sku_group AND w.wh_group = d.preferred_wh_group ), stage_1_alloc_ranked_for_facility AS ( SELECT *, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_pref_alloc, SUM(pref_alloc_qty) OVER ( PARTITION BY sku_group, preferred_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_pref_alloc_before FROM stage_1_group_alloc WHERE pref_alloc_qty > 0 ), stage_1_facility_stock_ranked AS ( SELECT *, SUM(wh_inventory) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fac_stock, SUM(wh_inventory) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fac_stock_before FROM perfume_wh_inventory ), stage_1_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, w.facility, w.wh_group, \'PREFERRED_WH\' AS allocation_stage, d.inventory_qty, d.jit_qty, d.stock_qty, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_qty, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_inventory AS warehouse_stock, GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_1_alloc_ranked_for_facility d JOIN stage_1_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.wh_group = d.preferred_wh_group WHERE GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) > 0 ), stage_1_facility_consumed AS ( SELECT sku_group, facility, SUM(allocated_qty) AS consumed_qty FROM stage_1_facility_alloc GROUP BY 1, 2 ), facility_stock_after_stage_1 AS ( SELECT w.sku_group, w.facility, w.wh_group, w.facility_order, w.wh_inventory, COALESCE(c.consumed_qty, 0) AS consumed_stage_1_qty, GREATEST(w.wh_inventory - COALESCE(c.consumed_qty, 0), 0) AS remaining_facility_stock FROM perfume_wh_inventory w LEFT JOIN stage_1_facility_consumed c ON c.sku_group = w.sku_group AND c.facility = w.facility ), stage_2_remaining_demand AS ( SELECT *, GREATEST(need_qty - pref_alloc_qty, 0) AS remaining_need_qty FROM stage_1_group_alloc WHERE GREATEST(need_qty - pref_alloc_qty, 0) > 0 ), stage_2_wh_group_stock AS ( SELECT sku_group, wh_group, SUM(remaining_facility_stock) AS remaining_group_stock FROM facility_stock_after_stage_1 GROUP BY 1, 2 ), stage_2_demand_ranked AS ( SELECT d.*, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_need_fallback, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_need_fallback_before FROM stage_2_remaining_demand d ), stage_2_group_alloc AS ( SELECT d.*, COALESCE(w.remaining_group_stock, 0) AS fallback_group_stock, GREATEST( LEAST(d.cum_need_fallback, COALESCE(w.remaining_group_stock, 0)) - COALESCE(d.cum_need_fallback_before, 0), 0 ) AS fallback_alloc_qty FROM stage_2_demand_ranked d LEFT JOIN stage_2_wh_group_stock w ON w.sku_group = d.sku_group AND w.wh_group = d.fallback_wh_group ), stage_2_alloc_ranked_for_facility AS ( SELECT *, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fallback_alloc, SUM(fallback_alloc_qty) OVER ( PARTITION BY sku_group, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, branch_code, branch_name ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_fallback_alloc_before FROM stage_2_group_alloc WHERE fallback_alloc_qty > 0 ), stage_2_facility_stock_ranked AS ( SELECT *, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_remaining_fac_stock, SUM(remaining_facility_stock) OVER ( PARTITION BY sku_group, wh_group ORDER BY facility_order, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) AS cum_remaining_fac_stock_before FROM facility_stock_after_stage_1 WHERE remaining_facility_stock > 0 ), stage_2_facility_alloc AS ( SELECT d.branch_code, d.branch_name, d.region, d.sku_group, w.facility, w.wh_group, \'FALLBACK_WH\' AS allocation_stage, d.inventory_qty, d.jit_qty, d.stock_qty, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_qty, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_inventory AS warehouse_stock, GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_2_alloc_ranked_for_facility d JOIN stage_2_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.wh_group = d.fallback_wh_group WHERE GREATEST( LEAST(d.cum_fallback_alloc, w.cum_remaining_fac_stock) - GREATEST( COALESCE(d.cum_fallback_alloc_before, 0), COALESCE(w.cum_remaining_fac_stock_before, 0) ), 0 ) > 0 ), final_allocation AS ( SELECT * FROM stage_1_facility_alloc UNION ALL SELECT * FROM stage_2_facility_alloc ) SELECT branch_code, branch_name, region, sku_group, NULL AS product_size, NULL AS size_sku_code, facility AS warehouse_name, wh_group, allocation_stage, NULL AS physical_size_qty, NULL AS jit_size_qty, NULL AS current_size_available, target_qty, need_qty, allocated_qty, warehouse_stock, inventory_qty AS store_inventory_qty, jit_qty AS store_jit_qty, stock_qty AS store_stock_jit_qty, NULL AS size_status, NULL AS size_remark, replen_priority_bucket, replen_priority_reason, option_count, ideal_options, current_options, option_gap, store_size, sales_last_7_days, sales_last_15_days, sales_last_30_days, ROUND(ros, 4) AS ros, ROUND(str, 4) AS str, ROUND(sell_through, 4) AS store_sell_through, preferred_wh_group, fallback_wh_group FROM final_allocation WHERE allocated_qty > 0 ORDER BY replen_priority_bucket ASC, sku_group, CASE WHEN allocation_stage = \'PREFERRED_WH\' THEN 1 ELSE 2 END, store_sell_through DESC, option_gap DESC, store_size DESC, ros DESC, branch_code, warehouse_name ), BAGS AS ( WITH store_sku_inventory AS ( SELECT *, COUNT(DISTINCT sku_group) OVER ( PARTITION BY branch_code, branch_name ) AS option_count FROM ( SELECT h.branch_code, UPPER(TRIM(h.marketplace_mapped)) AS branch_name, UPPER(TRIM(h.sku_group)) AS sku_group, SUM(COALESCE(h.inventory, 0)) AS inventory_qty, SUM(COALESCE(h.jit_qty, 0)) AS jit_qty, SUM(COALESCE(h.inventory, 0)) + SUM(COALESCE(h.jit_qty, 0)) AS stock_qty, SUM(COALESCE(h.sales_last_30_days, 0)) AS sales_last_30_days, SUM(COALESCE(h.sales_last_15_days, 0)) AS sales_last_15_days, SUM(COALESCE(h.sales_last_7_days, 0)) AS sales_last_7_days, ( 0.5 * (SUM(COALESCE(h.sales_last_7_days, 0)) / 7.0) + 0.3 * (SUM(COALESCE(h.sales_last_15_days, 0)) / 15.0) + 0.2 * (SUM(COALESCE(h.sales_last_30_days, 0)) / 30.0) ) AS ros, SUM(COALESCE(h.sales_last_30_days, 0)) / NULLIF( SUM(COALESCE(h.sales_last_30_days, 0)) + SUM(COALESCE(h.inventory, 0)), 0 ) AS str FROM snitch_db.maplemonk.offline_master h WHERE UPPER(TRIM(h.sku_group)) LIKE \'BP%\' AND COALESCE(h.inventory, 0) + COALESCE(h.jit_qty, 0) > 0 GROUP BY h.branch_code, UPPER(TRIM(h.marketplace_mapped)), UPPER(TRIM(h.sku_group)) ) ), stores_perf AS ( SELECT DISTINCT branch_code, branch_name AS marketplace_mapped FROM store_sku_inventory ), store_option_count AS ( SELECT branch_code, branch_name AS marketplace_mapped, MAX(option_count) AS option_count FROM store_sku_inventory GROUP BY 1, 2 ), store_region AS ( SELECT DISTINCT branch_code, UPPER(TRIM(zone)) AS region FROM snitch_db.maplemonk.store_category_delta ), schedule_rpl AS ( SELECT branch_code, UPPER(LEFT( CASE WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY rpl_order_day) = 1 ), store_sell_through AS ( SELECT branch_code, UPPER(TRIM(marketplace_mapped)) AS marketplace_mapped, SUM(COALESCE(sales_last_30_days, 0)) / NULLIF( (SUM(COALESCE(opening_inventory, 0)) + SUM(COALESCE(inventory, 0))) / 2.0, 0 ) AS sell_through FROM snitch_db.maplemonk.off_master_htmlbase WHERE UPPER(TRIM(sku_group)) LIKE \'BP%\' GROUP BY 1, 2 ), store_ideal_options AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(\"Bags(Options)\" AS INT), 0) AS ideal_options FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_size AS ( SELECT DISTINCT branch_code, COALESCE(TRY_CAST(REPLACE(sqft, \',\', \'\') AS INT), 0) AS store_size FROM snitch_db.maplemonk.offline_long_tail_sheet1 ), store_priority AS ( SELECT s.branch_code, s.marketplace_mapped, COALESCE(sr.region, \'UNKNOWN\') AS region, COALESCE(st.sell_through, 0) AS sell_through, COALESCE(io.ideal_options, 0) AS ideal_options, COALESCE(oc.option_count, 0) AS current_options, COALESCE(io.ideal_options, 0) - COALESCE(oc.option_count, 0) AS option_gap, COALESCE(sz.store_size, 0) AS store_size FROM stores_perf s LEFT JOIN store_region sr ON sr.branch_code = s.branch_code LEFT JOIN store_sell_through st ON st.branch_code = s.branch_code AND st.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_option_count oc ON oc.branch_code = s.branch_code AND oc.marketplace_mapped = s.marketplace_mapped LEFT JOIN store_ideal_options io ON io.branch_code = s.branch_code LEFT JOIN store_size sz ON sz.branch_code = s.branch_code INNER JOIN schedule_rpl sch ON sch.branch_code = s.branch_code AND UPPER(TRIM(sch.rpl_order_day)) = UPPER(DAYNAME(CURRENT_DATE)) ), wh_raw AS ( SELECT facility, UP