.sku_group, w.facility, w.wh_group, \'PREFERRED_WH\' AS allocation_stage, d.inventory_qty, d.jit_qty, d.stock_qty, d.replen_priority_bucket, d.replen_priority_reason, d.option_count, d.sales_last_30_days, d.sales_last_15_days, d.sales_last_7_days, d.ros, d.str, d.target_qty, d.need_qty, d.sell_through, d.ideal_options, d.current_options, d.option_gap, d.store_size, d.preferred_wh_group, d.fallback_wh_group, w.wh_inventory AS warehouse_stock, GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) AS allocated_qty FROM stage_1_alloc_ranked_for_facility d JOIN stage_1_facility_stock_ranked w ON w.sku_group = d.sku_group AND w.wh_group = d.preferred_wh_group WHERE GREATEST( LEAST(d.cum_pref_alloc, w.cum_fac_stock) - GREATEST( COALESCE(d.cum_pref_alloc_before, 0), COALESCE(w.cum_fac_stock_before, 0) ), 0 ) > 0 ), stage_1_facility_consumed AS ( SELECT sku_group, facility, SUM(allocated_qty) AS consumed_qty FROM stage_1_facility_alloc GROUP BY 1, 2 ), facility_stock_after_stage_1 AS ( SELECT w.sku_group, w.facility, w.wh_group, w.facility_order, w.wh_inventory, COALESCE(c.consumed_qty, 0) AS consumed_stage_1_qty, GREATEST(w.wh_inventory - COALESCE(c.consumed_qty, 0), 0) AS remaining_facility_stock FROM caps_wh_inventory w LEFT JOIN stage_1_facility_consumed c ON c.sku_group = w.sku_group AND c.facility = w.facility ), stage_2_remaining_demand AS ( SELECT *, GREATEST(need_qty - pref_alloc_qty, 0) AS remaining_need_qty FROM stage_1_group_alloc WHERE GREATEST(need_qty - pref_alloc_qty, 0) > 0 ), stage_2_wh_group_stock AS ( SELECT sku_group, wh_group, SUM(remaining_facility_stock) AS remaining_group_stock FROM facility_stock_after_stage_1 GROUP BY 1, 2 ), stage_2_demand_ranked AS ( SELECT d.*, SUM(remaining_need_qty) OVER ( PARTITION BY sku_group, fallback_wh_group ORDER BY replen_priority_bucket ASC, sell_through DESC, option_gap DESC, store_size DESC, ros DESC, str DESC, stock_qty ASC, b